/** N07 immutable byte intent, one initial PUT, exact physical recovery/readback and DOCUMENT registration. */
public final class DocumentReviewObjectLedger {
    private final JdbcTemplate db;private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();private final DependencyManifestSchema dependencies;private final SchemaCatalogue schemas;
    public DocumentReviewObjectLedger(DataSource data,DependencyManifestSchema dependencies)throws Exception{db=new JdbcTemplate(data);db.setQueryTimeout(5);this.dependencies=dependencies;schemas=SchemaCatalogue.fromClasspath();}
    Attempt prepare(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,String kind)throws Exception {
        p.requireCurrent(a);var t=p.terminal();var h=t.document().header();byte[] bytes=p.bytes(kind);String hash=WireValues.sha256(bytes);var pins=p.provenance();
        var rows=db.queryForList("SELECT * FROM document_review_object_intent WHERE tenant_id=? AND run_id=? AND step_id=? AND kind=? LIMIT 2 FOR UPDATE",h.tenantId(),t.runId(),t.stepId(),kind);boolean prior=!rows.isEmpty();Map<String,Object> row;
        if(prior)row=one(rows);else {
            String write=UUID.randomUUID().toString(),artifact=DocumentReviewResultService.artifact(t.hostActionId(),kind),key="tenants/"+h.tenantId()+"/document-review/"+t.runId()+"/"+write+"/"+artifact+".json";
            var intent=json.tree(Map.of("run_id",t.runId(),"step_id",t.stepId(),"action_id",t.hostActionId(),"kind",kind,"write_id",write,"artifact_id",artifact,"object_key",key,"payload_sha256",hash,"input_sha256",t.inputSha256(),"provenance",pins));
            row=meta(a,p,now());row.putAll(Map.of("run_id",t.runId(),"step_id",t.stepId(),"action_id",t.hostActionId(),"kind",kind,"write_id",write,"artifact_id",artifact,"object_key",key,"payload_sha256",hash,"canonical_payload",new String(bytes,StandardCharsets.UTF_8)));row.put("intent_json",json.canonical(intent));row.put("intent_sha256",json.hash(intent));insert("document_review_object_intent",row);
        }
        verify(p,kind,row);var attempts=db.queryForList("SELECT intent_sha256 FROM document_review_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",h.tenantId(),str(row,"write_id"));
        if(attempts.isEmpty()){if(prior)bad();var attempt=meta(a,p,now());attempt.put("write_id",str(row,"write_id"));attempt.put("intent_sha256",str(row,"intent_sha256"));insert("document_review_object_attempt",attempt);}else {same(str(row,"intent_sha256"),str(one(attempts),"intent_sha256"));prior=true;}
        return new Attempt(row,prior);
    }
    void requireTransfer(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,String kind,Attempt attempt)throws Exception {
        p.requireCurrent(a);if(attempt==null||attempt.owner!=this||!attempt.committed||attempt.thread!=Thread.currentThread())deny();
        var row=one(db.queryForList("SELECT * FROM document_review_object_intent WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",p.terminal().document().header().tenantId(),attempt.writeIntent().writeId()));verify(p,kind,row);same(str(row,"intent_sha256"),str(attempt.row,"intent_sha256"));
        var actual=one(db.queryForList("SELECT intent_sha256 FROM document_review_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",attempt.tenantId(),attempt.writeIntent().writeId()));same(str(row,"intent_sha256"),str(actual,"intent_sha256"));
    }
    Registered register(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,String kind,Attempt attempt,RuntimeObjectTransport.VerifiedTransfer physical)throws Exception {
        requireTransfer(a,p,kind,attempt);if(physical==null||physical.originalAttempt()!=attempt||!attempt.writeIntent().sha256().equals(physical.rawSha256()))bad();var t=p.terminal();var h=t.document().header();
        var old=db.queryForList("SELECT * FROM document_review_object WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",h.tenantId(),attempt.artifactId());if(!old.isEmpty())return registered(a,p,kind,one(old));
        var at=now();String access=DocumentReviewResultService.accessSet(t.hostActionId());var members=members(p);var manifest=new ArtifactRegistryProtocol.DependencyManifest("1.0.0",h.tenantId(),h.projectId(),access,members);String manifestHash=json.hash(manifest);
        var previous=db.queryForList("SELECT manifest_sha256 FROM dependency_access_set WHERE tenant_id=? AND access_set_id=? LIMIT 2 FOR UPDATE",h.tenantId(),access);
        if(previous.isEmpty()){
            version(h,access,"DEPENDENCY_ACCESS_SET",manifestHash);var set=meta(a,p,at);removeSchema(set);set.put("access_set_id",access);set.put("manifest_sha256",manifestHash);set.put("content_sha256",manifestHash);insert("dependency_access_set",set);
            var full=meta(a,p,at);full.putAll(Map.of("access_set_id",access,"manifest_json",json.canonical(manifest),"manifest_sha256",manifestHash,"content_sha256",manifestHash,"member_count",members.size()));full.put("schema_manifest_sha256",dependencies.manifestSha256());insert("dependency_access_manifest",full);
            for(var member:members){var item=meta(a,p,at);removeSchema(item);item.remove("project_id");item.putAll(Map.of("access_set_id",access,"upstream_version_id",member.upstreamVersionId(),"rights_revision",member.rightsRevision()));insert("dependency_access_member",item);}
        }else same(manifestHash,str(one(previous),"manifest_sha256"));
        var object=physical.reference();String artifact=attempt.artifactId();version(h,artifact,"ARTIFACT",object.sha256());
        var ar=meta(a,p,at);ar.putAll(Map.of("artifact_id",artifact,"run_id",t.runId(),"document_revision",h.documentRevision(),"artifact_kind",kind,"object_ref",StoredObjectReferences.encode(object),"object_key",object.objectKey(),"object_version",object.objectVersion(),"sha256",object.sha256(),"size_bytes",object.sizeBytes(),"media_type",object.mediaType()));ar.put("schema_manifest_sha256",p.schemaHash(kind));ar.put("dependency_access_set_id",access);ar.put("content_sha256",object.sha256());insert("artifact",ar);
        var binding=meta(a,p,at);removeSchema(binding);binding.putAll(Map.of("artifact_id",artifact,"resource_kind","DOCUMENT","resource_id",h.documentId(),"schema_ref",p.schemaRef(kind),"schema_document_sha256",p.schemaHash(kind),"dependency_access_set_id",access,"dependency_manifest_sha256",manifestHash));insert("artifact_content_binding",binding);
        for(String root:t.contentRoots())insert("lineage_edge",Map.of("tenant_id",h.tenantId(),"consumer_version_id",artifact,"upstream_version_id",root,"relation_kind","SAVED_DOCUMENT_REVIEW_INPUT","actor_id",a.actorId(),"created_at",at));
        String audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var receipt=json.tree(Map.of("schema_version","1.0.0","node_kind","N07","artifact_id",artifact,"kind",kind,"input_sha256",t.inputSha256(),"intent_sha256",str(attempt.row,"intent_sha256"),"object_ref",object,"provenance",p.provenance(),"audit_id",audit,"event_id",event));
        var saved=meta(a,p,at);saved.putAll(Map.of("run_id",t.runId(),"step_id",t.stepId(),"action_id",t.hostActionId(),"kind",kind,"artifact_id",artifact,"write_id",attempt.writeIntent().writeId(),"receipt_json",json.canonical(receipt),"receipt_sha256",json.hash(receipt)));insert("document_review_object",saved);
        var log=meta(a,p,at);log.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action","document.professional_review.object.registered","resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",t.hostActionId(),"trace_id",t.runId()));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",h.tenantId(),"event_id",event,"aggregate_id",artifact,"aggregate_revision",1,"event_type","document.professional_review.object.registered","payload",json.canonical(receipt),"occurred_at",at));
        p.requireCurrent(a);return registered(a,p,kind,one(db.queryForList("SELECT * FROM document_review_object WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",h.tenantId(),artifact)));
    }
    private List<ArtifactRegistryProtocol.MemberRow> members(DocumentReviewResultService.Produced p)throws Exception {
        var t=p.terminal();var out=new TreeMap<String,ArtifactRegistryProtocol.MemberRow>();for(var member:t.contentMembers())if(out.putIfAbsent(member.upstreamVersionId(),member)!=null)bad();
        if(!out.containsKey(t.document().header().bodyArtifactId())||!out.keySet().containsAll(t.rules().ruleIds())||!out.keySet().containsAll(t.contentRoots()))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
        return List.copyOf(out.values());
    }
    private Registered registered(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,String kind,Map<String,Object> row)throws Exception {
        p.requireCurrent(a);var t=p.terminal();var h=t.document().header();same(kind,str(row,"kind"));same(t.runId(),str(row,"run_id"));same(t.stepId(),str(row,"step_id"));same(t.hostActionId(),str(row,"action_id"));same(a.actorId(),str(row,"created_by"));var receipt=json.read(str(row,"receipt_json"));same(json.hash(receipt),str(row,"receipt_sha256"));same(t.inputSha256(),receipt.required("input_sha256").asText());same(p.provenance(),receipt.required("provenance"));
        var intent=one(db.queryForList("SELECT * FROM document_review_object_intent WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",h.tenantId(),str(row,"write_id")));verify(p,kind,intent);same(str(intent,"intent_sha256"),receipt.required("intent_sha256").asText());same(str(intent,"intent_sha256"),str(one(db.queryForList("SELECT intent_sha256 FROM document_review_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",h.tenantId(),str(row,"write_id"))),"intent_sha256"));
        var r=receipt.required("object_ref");var object=new InterfaceProtocol.ObjectRef(r.required("object_key").asText(),r.required("object_version").asText(),r.required("sha256").asText(),r.required("size_bytes").asText(),r.required("media_type").asText());same(WireValues.sha256(p.bytes(kind)),object.sha256());var artifact=one(db.queryForList("SELECT * FROM artifact WHERE tenant_id=? AND project_id=? AND artifact_id=? AND artifact_kind=? AND document_revision=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),str(row,"artifact_id"),kind,h.documentRevision()));StoredObjectReferences.decode(str(artifact,"object_ref"),object);same(p.schemaHash(kind),str(artifact,"schema_manifest_sha256"));
        var binding=one(db.queryForList("SELECT schema_ref,schema_document_sha256,resource_kind,resource_id FROM artifact_content_binding WHERE tenant_id=? AND artifact_id=? LIMIT 2",h.tenantId(),str(row,"artifact_id")));
        same(p.schemaRef(kind),str(binding,"schema_ref"));same(p.schemaHash(kind),str(binding,"schema_document_sha256"));same("DOCUMENT",str(binding,"resource_kind"));same(h.documentId(),str(binding,"resource_id"));same(DocumentReviewResultService.accessSet(t.hostActionId()),str(artifact,"dependency_access_set_id"));
        var audit=one(db.queryForList("SELECT resource_ref,result,subject_id FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",h.tenantId(),receipt.required("audit_id").asText()));same("SUCCESS",str(audit,"result"));same(a.actorId(),str(audit,"subject_id"));same(receipt,json.read(str(audit,"resource_ref")));same(receipt,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2 FOR UPDATE",h.tenantId(),receipt.required("event_id").asText())),"payload")));
        return new Registered(str(row,"artifact_id"),kind,object,str(row,"receipt_sha256"));
    }
    public final class Registered {
        private final String artifact,kind,receiptHash;private final InterfaceProtocol.ObjectRef reference;
        private Registered(String artifact,String kind,InterfaceProtocol.ObjectRef reference,String hash){this.artifact=artifact;this.kind=kind;this.reference=reference;receiptHash=hash;}
        void requireCurrent(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,String expected)throws Exception{same(expected,kind);var row=one(db.queryForList("SELECT * FROM document_review_object WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",p.terminal().document().header().tenantId(),artifact));var current=registered(a,p,kind,row);same(receiptHash,current.receiptHash);same(reference,current.reference);}
        public String artifactId(){return artifact;}public InterfaceProtocol.ObjectRef reference(){return reference;}
    }
    public final class Attempt implements RuntimeObjectAttempt {
        private final DocumentReviewObjectLedger owner=DocumentReviewObjectLedger.this;private final Map<String,Object> row;private final boolean prior;private boolean committed;private final Thread thread=Thread.currentThread();private final java.util.concurrent.atomic.AtomicBoolean claimed=new java.util.concurrent.atomic.AtomicBoolean();
        private Attempt(Map<String,Object> row,boolean prior){this.row=Map.copyOf(row);this.prior=prior;if(!TransactionSynchronizationManager.isSynchronizationActive())deny();TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){committed=true;}});}
        public String tenantId(){return str(row,"tenant_id");}public String actorId(){return str(row,"created_by");}public String artifactId(){return str(row,"artifact_id");}public String expectedObjectKey(){return str(row,"object_key");}public byte[] bytes(){return str(row,"canonical_payload").getBytes(StandardCharsets.UTF_8);}public boolean priorAttempt(){return prior;}public S3ObjectWriter.WriteIntent writeIntent(){return new S3ObjectWriter.WriteIntent(str(row,"write_id"),expectedObjectKey(),str(row,"payload_sha256"),Integer.toString(bytes().length),"application/json");}public TransferMode claimTransferMode(){if(!committed||thread!=Thread.currentThread()||TransactionSynchronizationManager.isActualTransactionActive())deny();return prior||!claimed.compareAndSet(false,true)?TransferMode.RECOVER_ONLY:TransferMode.INITIAL_WRITE;}
    }
    private void verify(DocumentReviewResultService.Produced p,String kind,Map<String,Object> row)throws Exception {var t=p.terminal();same(t.runId(),str(row,"run_id"));same(t.stepId(),str(row,"step_id"));same(t.hostActionId(),str(row,"action_id"));same(kind,str(row,"kind"));same(WireValues.sha256(p.bytes(kind)),str(row,"payload_sha256"));if(!Arrays.equals(p.bytes(kind),str(row,"canonical_payload").getBytes(StandardCharsets.UTF_8)))bad();var intent=json.read(str(row,"intent_json"));same(json.hash(intent),str(row,"intent_sha256"));same(p.provenance(),intent.required("provenance"));for(String k:List.of("run_id","step_id","action_id","kind","write_id","artifact_id","object_key","payload_sha256"))same(str(row,k),intent.required(k).asText());same(t.inputSha256(),intent.required("input_sha256").asText());}

    private void version(DocumentReadProtocol.Header h,String id,String kind,String hash){insert("version_registry",Map.of("tenant_id",h.tenantId(),"version_id",id,"owner_project_id",h.projectId(),"entity_kind",kind,"content_sha256",hash));}
    private Map<String,Object> meta(EnterpriseAccess.Admission a,DocumentReviewResultService.Produced p,LocalDateTime at)throws Exception{var h=p.terminal().document().header();var row=new LinkedHashMap<String,Object>();row.put("tenant_id",h.tenantId());row.put("project_id",h.projectId());row.put("created_by",a.actorId());row.put("created_at",at);row.put("classification",h.classification());row.put("schema_version","1.0.0");row.put("schema_manifest_sha256",schemas.schemaDigest("artifacts"));return row;}private static void removeSchema(Map<String,Object> row){row.remove("schema_version");row.remove("schema_manifest_sha256");}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}private LocalDateTime now(){return db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class);}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static String str(Map<String,Object> row,String key){var v=row.get(key);if(v==null)bad();return v.toString();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
